input.command:
cd /tmp && rm -f av_check.db && sqlite3 av_check.db <<'SQL'
CREATE TABLE orders (id INTEGER PRIMARY KEY, shipped_at TEXT, cancelled_at TEXT);
INSERT INTO orders VALUES (1, '2026-08-01', NULL);   -- shipped
INSERT INTO orders VALUES (2, NULL, NULL);           -- open
INSERT INTO orders VALUES (3, NULL, '2026-08-02');   -- cancelled, never shipped
INSERT INTO orders VALUES (4, '2026-08-03', '2026-08-05'); -- shipped then cancelled/returned
ALTER TABLE orders ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'pending';
CREATE INDEX idx_orders_status ON orders(status);
UPDATE orders SET status = 'fulfilled' WHERE shipped_at IS NOT NULL;
-- simulate an order that ships after the backfill, before app writes status
INSERT INTO orders (id, shipped_at) VALUES (5, '2026-08-26');
.mode column
.headers on
SELECT id, shipped_at, cancelled_at, status FROM orders ORDER BY id;
SELECT '--- rerun check ---';
SQL
echo "exit=$?"; echo "--- second run of migration on same DB (idempotency) ---"
sqlite3 av_check.db "ALTER TABLE orders ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'pending';" 2>&1; echo "exit=$?"
